import { describe, expect, it } from "vitest";
import { existsSync, readFileSync } from "fs";
import { join } from "path";
import { diarize } from "./features/speakers";
import { detectSilences } from "./features/silence";

/**
 * REAL-VOICE EVALUATION of the classical speaker/silence detectors on recorded speech (macOS voices, generated by
 * the Phase 14 test procedure into .tmp-test-assets/phase14 — git-ignored, so this suite SKIPS where the files don't
 * exist). Assertions are the accuracy actually measured, including the known failure on two similar male voices.
 */
const DIR = join(process.cwd(), ".tmp-test-assets", "phase14");
const has = (f: string) => existsSync(join(DIR, f));

function readWav(file: string): Float32Array {
  const b = readFileSync(join(DIR, file));
  let o = 12;
  while (o < b.length) {
    const id = b.toString("ascii", o, o + 4);
    const sz = b.readUInt32LE(o + 4);
    if (id === "data") {
      const data = b.subarray(o + 8, o + 8 + sz);
      return Float32Array.from({ length: data.length / 2 }, (_, i) => data.readInt16LE(i * 2) / 32768);
    }
    o += 8 + sz + (sz % 2);
  }
  throw new Error("no data chunk");
}

function accuracy(turns: { start: number; end: number; speaker: number }[], bounds: number[], truth: number[], dur: number): number {
  const truthAt = (t: number) => truth[bounds.filter((b) => t > b).length];
  const hypAt = (t: number) => turns.find((x) => t >= x.start && t < x.end)?.speaker ?? -1;
  const co = new Map<string, number>();
  for (let t = 0; t < dur; t += 0.05) co.set(`${truthAt(t)}:${hypAt(t)}`, (co.get(`${truthAt(t)}:${hypAt(t)}`) ?? 0) + 1);
  const map = new Map<number, number>();
  [...co.entries()].sort((a, b) => b[1] - a[1]).forEach(([k]) => {
    const [tr, hy] = k.split(":").map(Number);
    if (!map.has(hy) && ![...map.values()].includes(tr)) map.set(hy, tr);
  });
  let ok = 0;
  let n = 0;
  for (let t = 0; t < dur; t += 0.05, n++) if (map.get(hypAt(t)) === truthAt(t)) ok++;
  return ok / n;
}

describe.skipIf(!has("interview-2spk.wav"))("real voices: speaker detection", () => {
  it("two clearly different voices: 2 speakers, >95% of time correct, turn changes inside the pauses", () => {
    const x = readWav("interview-2spk.wav");
    const r = diarize(x);
    expect(r.speakers).toBe(2);
    expect(accuracy(r.turns, [5.38, 12.12, 17.16], [0, 1, 0, 1], x.length / 16000)).toBeGreaterThan(0.95);
    r.turns.slice(1).forEach((t, i) => expect(Math.abs(t.start - [5.38, 12.12, 17.16][i])).toBeLessThan(0.25));
  });

  it("one voice: one speaker", () => {
    expect(diarize(readWav("mono-1spk.wav")).speakers).toBe(1);
  });

  it("KNOWN LIMIT: two male voices of similar pitch (Daniel ~112 Hz, Fred ~107 Hz) are merged", () => {
    const x = readWav("panel-3spk.wav");
    const r = diarize(x);
    expect(r.speakers).toBe(2); // truth is 3
    expect(accuracy(r.turns, [5.38, 12.12, 18.07], [0, 1, 2, 0], x.length / 16000)).toBeLessThan(0.8);
  });
});

describe.skipIf(!has("interview-2spk.wav"))("real voices: silence detection", () => {
  it("finds the three 0.4 s pauses between turns (min duration 0.3 s)", () => {
    const x = readWav("interview-2spk.wav");
    const { ranges } = detectSilences(x, 16000, { minDuration: 0.3 });
    for (const b of [5.38, 12.12, 17.16]) expect(ranges.some((r) => r.start <= b && r.end >= b)).toBe(true);
  });
});
